import type {OutgoingMessage} from './messages.js';

export interface TextMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ToolCallContent {
  type: 'tool_use';
  toolUseId: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResultContent {
  type: 'tool_result';
  toolUseId: string;
  content: string;
}

export interface ToolUseMessage {
  role: 'assistant';
  content: ToolCallContent[];
}

export interface ToolResultMessage {
  role: 'user';
  content: ToolResultContent[];
}

export type Message = TextMessage | ToolUseMessage | ToolResultMessage;

export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  promptInstructions?: string;
  examplePrompts?: string[];
}

export interface ToolCall {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export type MessageChunk =
  | {type: 'text'; text: string}
  | {type: 'tool_use'; toolCall: ToolCall}
  | {type: 'tool_result'; clientMessages: OutgoingMessage[]}
  | {type: 'suppress_output'}
  | {type: 'stop'; stopReason: string; usage?: UsageMetadata};

export interface SendMessageParams {
  messages: Message[];
  systemPrompt: string;
  tools?: ToolDefinition[];
  maxTokens?: number;
}

export interface StructuredOutputParams<_T> {
  messages: Message[];
  systemPrompt: string;
  responseSchema: ResponseSchema;
  maxTokens?: number;
}

export interface ResponseSchema {
  type: 'object' | 'array' | 'string' | 'number' | 'boolean';
  properties?: Record<string, ResponseSchema>;
  items?: ResponseSchema;
  required?: string[];
  description?: string;
  enum?: string[];
}

export interface UsageMetadata {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

export interface AIProviderResponse {
  usage?: UsageMetadata;
}

export interface AIProvider {
  sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk>;
  generateStructured<T>(params: StructuredOutputParams<T>): Promise<T>;
}

export class AIError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    // eslint-disable-next-line re-lint/no-flag-params -- public API; splitting AIError is a breaking change (adrs/ADR-006-lint-suppressions.md)
    public readonly retryable: boolean = false
  ) {
    super(message);
    this.name = 'AIError';
  }
}
specs/hal-engine-config-hooks/spec.md:8:`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.
specs/hal-engine-config-hooks/spec.md:16:- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L132)).
specs/hal-engine-config-hooks/spec.md:25:These properties of `src/orchestration/chatOrchestrator.ts` record the measured semantics that hook features specify against. The `onError` boundary remains out of scope; issue #93 defines the aggregate usage delivered after tool rounds.
specs/hal-engine-config-hooks/spec.md:28:- `afterModelResponse` is called once per user message after the round loop exits and receives the summed provider-call usage for the entire turn, so tool rounds are included in a deployer's billing or audit total ([validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L44), [validated by: sums usage reported by every provider round](../../src/orchestration/chatOrchestrator.test.ts#L527)).
CHANGELOG.md:5:The format is [Keep a Changelog 1.1.0](https://keepachangelog.com/en/1.1.0/), and this project adheres to
CHANGELOG.md:39:- `HalEngineConfig.transport` now accepts three optional extension points: `additionalRoutes` (mounts a router under `basePath`, unauthenticated), `rootRoutes` (mounts a router at `/`, after the `basePath` router and before the 404 catch-all), and `errorHandler` (replaces Express's default HTML error page). Pass none of them and the app is identical to before. See `docs/getting-started.md` for usage and the GDPR / NIS-2 notes that apply to unauthenticated routes.
CHANGELOG.md:41:- `OrchestratorHooks` gains an optional `onToolBudgetExhausted(session, budget)` hook, and `ToolBudgetInfo` (`{maxToolRounds, requestedTools}`) and `TOOL_BUDGET_EXHAUSTED` are exported. It fires when the model asks for a tool round `maxToolRounds` refuses, after the last provider call and before `afterModelResponse`. Return a sentence and the turn ends on it as an ordinary assistant entry, so the user sees a degraded answer instead of silence; the engine writes no prose of its own. Every exhausted run now also ends with a `{type: 'stop', stopReason: 'tool_budget_exhausted'}` chunk, a new value for the existing field rather than a new type, which the WebSocket transport sends nothing for. The turn still ends with `stream_end`, never `error`. Additive: with no hook installed, the wire is unchanged.

#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
      return rewrite(atLine.name, groups.path, atLine.line);
    }

    // Checked before the line is consulted: a name that identifies two declarations is not an
    // identifier, and while the line happens to agree nothing would ever say so.
    if (nameIsAmbiguous(declarations, named)) {
      findings.push(ambiguity(spec, groups.path, named, declarations));
      return whole;
    }

    if (atLine && atLine.name === named) return whole;

    const [match] = declarations.filter(declaration => declaration.name === named);
    if (!match) {
      findings.push(`${spec}: names "${named}", which no declaration in ${groups.path} has`);
      return whole;
    }
    if (!fix) {
      findings.push(`${spec}: names "${named}" but points at #L${groups.line}; it is at #L${match.line}`);
      return whole;
    }
    return rewrite(named, groups.path, match.line);

    function rewrite(name, path, line) {
      // A name carrying a bracket would close the markdown label early: the citation stops being a
      // link, stops matching CITATION, and disappears from this gate and from the coverage job.
      if (/[[\]]/.test(name)) {
        findings.push(`${spec}: "${name}" carries a bracket and cannot be written into a markdown label`);
        return whole;
      }
      repaired += 1;
      changed = true;
      return citation(name, path, line);
    }
  });

  if (changed) writeFileSync(join(root, spec), rewritten);
}

